// The grantee is a group name or a space name, which stands for the user that space's plugin logs in as.
const granteeUid = async (granteeName: string): Promise<string> => {
  const localRefs = (world.localRefs || {}) as LocalRefsType;
  const ref = localRefs[granteeName];
  if (typeof ref === "string") return ref;
  return spaceUid(granteeName);
};

const GRANT_TABLES = ["SpaceAccess", "ResourceAccess"] as const;
type GrantTable = (typeof GRANT_TABLES)[number];

const grantRow = async ({
  table,
  spaceName,
  granteeName,
}: {
  table: string;
  spaceName: string;
  granteeName: string;
}): Promise<{ table: GrantTable; row: Record<string, unknown> }> => {
  if (!GRANT_TABLES.includes(table as GrantTable))
    assert.fail(`unknown grant table ${table}`);
  const localRefs = (world.localRefs || {}) as LocalRefsType;
  const spaceId = localRefs[spaceName];
  if (typeof spaceId !== "number") assert.fail(`unknown space ${spaceName}`);
  const accountUid = await granteeUid(granteeName);
  return {
    table: table as GrantTable,
    row:
      table === "SpaceAccess"
        ? {
            space_id: spaceId,
            account_uid: accountUid,
            permissions: "partial",
          }
        : {
            space_id: spaceId,
            account_uid: accountUid,
            source_local_id: "granted",
          },
  };
};

const insertGrant = async ({
  writerSpaceName,
  table,
  spaceName,
  granteeName,
}: {
  writerSpaceName: string;
  table: string;
  spaceName: string;
  granteeName: string;
}): Promise<{ error: { code: string } | null }> => {
  const { client } = await getSpaceClient(writerSpaceName);
  const grant = await grantRow({ table, spaceName, granteeName });
  return client.from(grant.table).insert(grant.row as never);
};

