    granteeName: string,
  ): Promise<void> => {
    const response = await insertGrant({
      writerSpaceName,
      table,
      spaceName,
      granteeName,
    });
    assert.equal(response.error?.code, INSUFFICIENT_PRIVILEGE);
  },
);

// A refused update matches the row but fails the policy's check on the new row, so it returns an error.
Then(
  "user of space {word} fails to move its {word} in space {word} from {word} to {word}",
  async (
    writerSpaceName: string,
    table: string,
    spaceName: string,
    fromName: string,
    toName: string,
  ): Promise<void> => {
    const { client } = await getSpaceClient(writerSpaceName);
    const grant = await grantRow({ table, spaceName, granteeName: fromName });
    const response = await untyped(client)
      .from(grant.table)
      .update({ account_uid: await granteeUid(toName) })
      .match(grant.row)
      .select();
    assert.equal(response.error?.code, INSUFFICIENT_PRIVILEGE);
  },
);
